    def __init__(self, msg='Invalid pattern(s) found.'):
        self.msg = msg

    def __str__(self):
        s = self._format()
        if isinstance(s, unicode):
            s = s.encode('utf8')
        else:
            # __str__ must return a str.
            s = str(s)
        return s

